mapper.select:
SELECT p.id, p.name, p.category_id AS categoryId, c.name AS categoryName, p.brand, p.spec, p.price, p.cost_price AS costPrice, p.stock, p.safe_stock AS safeStock, p.unit, p.image_url AS imageUrl, p.description, p.status, p.created_at AS createdAt FROM product p LEFT JOIN product_category c ON p.category_id = c.id AND c.deleted = 0 WHERE p.deleted = 0
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND p.category_id = #{categoryId}
AND p.status = #{status}
ORDER BY p.created_at DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM product p
WHERE p.deleted = 0

    AND p.name LIKE CONCAT('%', #{keyword}, '%')


    AND p.category_id = #{categoryId}


    AND p.status = #{status}
